{"draft":{"version":"a0","html":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pop the Bubbles</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background: #fbf7ee;
    overflow: hidden;
    font-family: "Arial Narrow", Arial, sans-serif;
  }
  #game-wrap {
    position: relative;
    width: 100vw;
    height: 100dvh;
  }
  canvas {
    display: block;
    width: 100%;
    height: 100%;
    touch-action: none;
  }
  #clearBtn {
    position: absolute;
    top: 14px;
    right: 14px;
    min-width: 100px;
    min-height: 48px;
    background: #0078bf;
    color: #fbf7ee;
    border: 3px solid #5b3a8c;
    border-radius: 10px;
    font-family: "Arial Narrow", Arial, sans-serif;
    font-weight: bold;
    font-size: 18px;
    letter-spacing: 1px;
    text-transform: uppercase;
    cursor: pointer;
    padding: 8px 14px;
    box-shadow: 2px 2px 0 #ff48b0;
  }
  #clearBtn:active {
    transform: translate(1px, 1px);
    box-shadow: 1px 1px 0 #ff48b0;
  }
  #tally {
    position: absolute;
    top: 14px;
    left: 14px;
    font-weight: bold;
    font-size: 22px;
    color: #0078bf;
    text-shadow: 2px 2px 0 #ff48b0;
    letter-spacing: 1px;
    user-select: none;
  }
</style>
</head>
<body>
<div id="game-wrap">
  <canvas id="canvas"></canvas>
  <div id="tally">POPS: 0</div>
  <button id="clearBtn">Clear</button>
</div>
<script>
  const CARTRIDGE = {
    send(type, payload = {}) {
      window.parent.postMessage(
        { source: "cartridge", v: 1, type, payload },
        "*",
      );
    },
  };
</script>
<script>
(function() {
  const canvas = document.getElementById("canvas");
  const ctx = canvas.getContext("2d");
  const tallyEl = document.getElementById("tally");
  const clearBtn = document.getElementById("clearBtn");

  let dpr = Math.max(1, window.devicePixelRatio || 1);
  let W = 0, H = 0;

  function resize() {
    W = window.innerWidth;
    H = window.innerHeight;
    dpr = Math.max(1, window.devicePixelRatio || 1);
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    buildGrain();
  }

  // Pre-rendered grain tile
  let grainCanvas = null;
  function buildGrain() {
    const size = 128;
    grainCanvas = document.createElement("canvas");
    grainCanvas.width = size;
    grainCanvas.height = size;
    const gctx = grainCanvas.getContext("2d");
    const imgData = gctx.createImageData(size, size);
    for (let i = 0; i < imgData.data.length; i += 4) {
      const v = Math.floor(Math.random() * 255);
      imgData.data[i] = v;
      imgData.data[i + 1] = v;
      imgData.data[i + 2] = v;
      imgData.data[i + 3] = 255;
    }
    gctx.putImageData(imgData, 0, 0);
  }

  function drawGrain() {
    if (!grainCanvas) return;
    const pattern = ctx.createPattern(grainCanvas, "repeat");
    ctx.save();
    ctx.globalAlpha = 0.08;
    ctx.fillStyle = pattern;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  // Game state
  let running = false;
  let paused = false;
  let tally = 0;
  const bubbles = [];
  let lastSpawn = 0;
  let spawnInterval = 900;
  const inks = ["#ff48b0", "#0078bf"];

  function rand(min, max) {
    return Math.random() * (max - min) + min;
  }

  function spawnBubble() {
    const r = rand(24, 46);
    bubbles.push({
      x: rand(r, W - r),
      y: H + r + rand(0, 60),
      r: r,
      speed: rand(18, 42) / 60,
      wobble: rand(0, Math.PI * 2),
      wobbleSpeed: rand(0.01, 0.03),
      wobbleAmp: rand(4, 14),
      ink: inks[Math.floor(Math.random() * inks.length)],
      popped: false,
      popT: 0,
    });
  }

  function settle(dt) {
    lastSpawn += dt;
    if (lastSpawn > spawnInterval && bubbles.length < 40) {
      lastSpawn = 0;
      spawnBubble();
    }
    for (let i = bubbles.length - 1; i >= 0; i--) {
      const b = bubbles[i];
      if (b.popped) {
        b.popT += dt;
        if (b.popT > 220) bubbles.splice(i, 1);
        continue;
      }
      b.y -= b.speed * dt;
      b.wobble += b.wobbleSpeed * dt;
      if (b.y < -b.r - 60) {
        bubbles.splice(i, 1);
      }
    }
  }

  function drawHalftoneShade(x, y, r, color) {
    // subtle halftone dots to fake shading inside bubble
    ctx.save();
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = color;
    const step = Math.max(4, r / 5);
    for (let yy = y - r; yy < y + r; yy += step) {
      for (let xx = x - r; xx < x + r; xx += step) {
        const d = Math.hypot(xx - x, yy - y) / r;
        if (d > 0.55 && d < 0.95) {
          const dotR = step * 0.22;
          ctx.beginPath();
          ctx.arc(xx, yy, dotR, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
    ctx.restore();
  }

  function drawBubble(b) {
    const wob = Math.sin(b.wobble) * b.wobbleAmp * 0.15;
    const x = b.x + wob;
    const y = b.y;

    if (b.popped) {
      // pop burst: a few offset shards
      const t = b.popT / 220;
      const alpha = 1 - t;
      ctx.save();
      ctx.globalAlpha = Math.max(0, alpha);
      ctx.strokeStyle = b.ink;
      ctx.lineWidth = 3;
      const spikes = 8;
      for (let i = 0; i < spikes; i++) {
        const ang = (i / spikes) * Math.PI * 2;
        const dist = b.r * (0.6 + t * 1.2);
        const px = x + Math.cos(ang) * dist;
        const py = y + Math.sin(ang) * dist;
        ctx.beginPath();
        ctx.moveTo(x + Math.cos(ang) * b.r * 0.3, y + Math.sin(ang) * b.r * 0.3);
        ctx.lineTo(px, py);
        ctx.stroke();
      }
      ctx.restore();
      return;
    }

    // misregistration offset layer (second ink slightly offset)
    ctx.save();
    ctx.globalAlpha = 0.55;
    ctx.fillStyle = b.ink === inks[0] ? inks[1] : inks[0];
    ctx.beginPath();
    ctx.arc(x + 2, y + 2, b.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // main flat fill
    ctx.save();
    ctx.fillStyle = b.ink;
    ctx.beginPath();
    ctx.arc(x, y, b.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    drawHalftoneShade(x, y, b.r, "#fbf7ee");

    // outline
    ctx.save();
    ctx.strokeStyle = "#5b3a8c";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(x, y, b.r, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }

  function drawTitleScreen() {
    ctx.fillStyle = "#fbf7ee";
    ctx.fillRect(0, 0, W, H);

    // decorative static bubbles
    ctx.save();
    ctx.globalAlpha = 0.6;
    for (let i = 0; i < 6; i++) {
      const r = 30 + (i % 3) * 12;
      const x = (W / 7) * (i + 1);
      const y = H * 0.35 + Math.sin(i) * 40;
      ctx.fillStyle = i % 2 === 0 ? "#ff48b0" : "#0078bf";
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();

    ctx.save();
    ctx.textAlign = "center";
    ctx.fillStyle = "#5b3a8c";
    ctx.font = "bold 44px 'Arial Narrow', Arial, sans-serif";
    ctx.fillText("POP THE BUBBLES", W / 2, H * 0.55);
    ctx.restore();

    const pulse = 0.6 + 0.4 * Math.sin(performance.now() / 300);
    ctx.save();
    ctx.globalAlpha = pulse;
    ctx.textAlign = "center";
    ctx.fillStyle = "#ff48b0";
    ctx.font = "bold 26px 'Arial Narrow', Arial, sans-serif";
    ctx.fillText("TAP TO BEGIN", W / 2, H * 0.65);
    ctx.restore();

    drawGrain();
  }

  function draw() {
    ctx.fillStyle = "#fbf7ee";
    ctx.fillRect(0, 0, W, H);

    if (!running) {
      drawTitleScreen();
      return;
    }

    for (const b of bubbles) drawBubble(b);

    if (paused) {
      ctx.save();
      ctx.fillStyle = "rgba(91,58,140,0.5)";
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = "#fbf7ee";
      ctx.textAlign = "center";
      ctx.font = "bold 34px 'Arial Narrow', Arial, sans-serif";
      ctx.fillText("PAUSED", W / 2, H / 2);
      ctx.restore();
    }

    drawGrain();
  }

  function updateTallyDisplay() {
    tallyEl.textContent = "POPS: " + tally;
  }

  function clearTable() {
    bubbles.length = 0;
    tally = 0;
    updateTallyDisplay();
    CARTRIDGE.send("score", { value: 0 });
    draw();
  }

  function backToTitle() {
    running = false;
    paused = false;
    clearTable();
    draw();
  }

  function tryPop(px, py) {
    for (let i = bubbles.length - 1; i >= 0; i--) {
      const b = bubbles[i];
      if (b.popped) continue;
      const wob = Math.sin(b.wobble) * b.wobbleAmp * 0.15;
      const dx = px - (b.x + wob);
      const dy = py - b.y;
      if (Math.hypot(dx, dy) <= b.r) {
        b.popped = true;
        b.popT = 0;
        tally += 1;
        updateTallyDisplay();
        CARTRIDGE.send("score", { value: tally });
        return true;
      }
    }
    return false;
  }

  canvas.style.touchAction = "none";
  canvas.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    if (paused) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    if (!running) {
      running = true;
      CARTRIDGE.send("start");
      // seed a few bubbles right away
      for (let i = 0; i < 5; i++) spawnBubble();
      return;
    }
    tryPop(x, y);
  });

  clearBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    clearTable();
  });
  clearBtn.addEventListener("pointerdown", (e) => {
    e.stopPropagation();
  });

  window.addEventListener("message", (event) => {
    const data = event.data;
    if (!data || data.source !== "cartridge-host") return;
    if (data.type === "pause") paused = true;
    if (data.type === "resume") paused = false;
    if (data.type === "reset") backToTitle();
  });

  window.addEventListener("resize", resize);

  let lastTime = performance.now();
  function frame(now) {
    const dt = Math.min(50, now - lastTime);
    lastTime = now;
    if (!paused && running) settle(dt);
    draw();
    requestAnimationFrame(frame);
  }

  resize();
  draw();
  CARTRIDGE.send("boot", { title: "Pop the Bubbles", gameType: "toy-box", lang: "en" });
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
"}}

